            raise KakaoMapConnectionError(f"Request failed: {e}")
        except Exception as e:
            LOGGER.error(f"Unexpected error in KakaoMap transport API request: {e}")
            raise KakaoMapDataError(f"Unexpected error: {e}")

    def _parse_address_response(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Parse address response data."""
        try:
            result = {
                "success": True,
                "address": None,
                "region": None,
                "coordinates": None
            }

            if "old" in data and data["old"]:
                old_data = data["old"]
                result["address"] = old_data.get("name", "")
                result["region"] = data.get("region", "")
                result["coordinates"] = {
                    "x": data.get("x"),
                    "y": data.get("y")
                }

            return result

        except Exception as e:
            LOGGER.error(f"Error parsing address response: {e}")
            raise KakaoMapDataError(f"Address parsing failed: {e}")

    def _parse_transport_response(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Parse transport route response data."""
        try:
            result = {
                "success": True,
                "routes": [],
                "summary": {
                    "total_routes": 0,
                    "fastest_route": None,
                    "recommended_route": None
                }
            }

            in_local = data.get("in_local")
            if not in_local or in_local.get("status") != "OK":
                result["success"] = False
                return result

            routes = in_local.get("routes", [])
            result["summary"]["total_routes"] = len(routes)

            for route in routes:
                parsed_route = {
                    "ranking": route.get("ranking"),
                    "type": route.get("type"),
                    "distance": route.get("distance", {}).get("text", ""),
                    "time": route.get("time", {}).get("text", ""),
                    "time_value": route.get("time", {}).get("value", 0),
                    "walking_distance": route.get("walkingDistance", {}).get("text", ""),
                    "walking_time": route.get("walkingTime", {}).get("text", ""),
                    "transfers": route.get("transfers", 0),
                    "fare": route.get("fare", {}).get("text", ""),
                    "fare_value": route.get("fare", {}).get("value", 0),
                    "recommended": route.get("recommended", False),
                    "shortest_time": route.get("shortestTime", False),
                    "summaries": route.get("summaries", [])
                }

                result["routes"].append(parsed_route)

                # Set fastest and recommended routes
                if route.get("shortestTime"):
                    result["summary"]["fastest_route"] = parsed_route
                if route.get("recommended"):
                    result["summary"]["recommended_route"] = parsed_route

            return result

        except Exception as e:
            LOGGER.error(f"Error parsing transport response: {e}")
            raise KakaoMapDataError(f"Transport parsing failed: {e}")

    def get_route_summary(self, transport_data: Dict[str, Any]) -> str:
        """Get a summary string of the transport routes."""
        if not transport_data.get("success") or not transport_data.get("routes"):
            return "경로 정보 없음"
        recommended = transport_data["summary"].get("recommended_route")
        if recommended:
            return f"{recommended['time']} ({recommended['fare']}, 환승 {recommended['transfers']}회)"

        # Fall back to first route
        first_route = transport_data["routes"][0]
        return f"{first_route['time']} ({first_route['fare']}, 환승 {first_route['transfers']}회)"

"""Safety Alert API client for Home Assistant integration.""" from __future__ import annotations
import aiohttp import ssl from typing import Dict, Any, List, Optional from datetime import datetime, timedelta
from .exceptions import SafetyAlertConnectionError, SafetyAlertDataError from ..const import LOGGER
class SafetyAlertApiClient: """API client for Safety Alert integration."""
def __init__(self, session: aiohttp.ClientSession) -> None: """Initialize the Safety Alert API client.""" self._session: aiohttp.ClientSession = session self._base_url: str = "https://www.safekorea.go.kr/idsiSFK/sfk/cs/sua/web/DisasterSmsList.do"
# SSL 컨텍스트 설정 - DH_KEY_TOO_SMALL 에러 해결 self._ssl_context = ssl.create_default_context() self._ssl_context.set_ciphers('ECDHE+AESGCM:ECDHE+CHACHA20:DHE+AESGCM:DHE+CHACHA20:!aNULL:!MD5:!DSS')
# TLS 1.2 이상만 사용하도록 설정 self._ssl_context.options |= ssl.OP_NO_SSLv2 | ssl.OP_NO_SSLv3 | ssl.OP_NO_TLSv1 | ssl.OP_NO_TLSv1_1
async def async_get_safety_alerts( self, area_code: str = "1156000000", area_code2: Optional[str] = None, area_code3: Optional[str] = None ) -> List[Dict[str, Any]]: """Get safety alerts for the specified areas.""" # Calculate date range (last 7 days) end_date = datetime.now() start_date = end_date - timedelta(days=7)
# Prepare request payload with all area codes payload = { "searchInfo": { "firstIndex": "1", "rcv_Area_Id": "", "pageIndex": "1", "sbLawArea1": area_code, # 첫 번째 지역 코드 "dstr_se_Id": "", "lastIndex": "1", "searchBgnDe": start_date.strftime("%Y-%m-%d"), "searchEndDe": end_date.strftime("%Y-%m-%d"), "sbLawArea3": area_code3 if area_code3 else "", # 세 번째 지역 코드 "recordCountPerPage": "50", "searchWrd": "", "searchGb": "1", "c_ocrc_type": "", "sbLawArea2": area_code2 if area_code2 else "", # 두 번째 지역 코드 "pageUnit": "50", "pageSize": 50 } }
headers = { "Content-Type": "application/json", "Accept": "application/json", "User-Agent": "HomeAssistant-Korea-Components/1.0" }
try: async with self._session.post( self._base_url, json=payload, headers=headers, ssl=self._ssl_context # SSL 컨텍스트 적용 ) as response: LOGGER.debug(f"Safety Alert API response status: {response.status}")
if response.status != 200: LOGGER.warning(f"Failed to get alerts: HTTP {response.status}") raise SafetyAlertConnectionError(f"HTTP {response.status}")
data = await response.json() LOGGER.debug(f"Safety Alert API response: {data}") alerts = data.get("disasterSmsList", [])
# 생성일시 기준으로 정렬 (최신순) alerts.sort(key=lambda x: x.get("CREAT_DT", ""), reverse=True) return alerts
except aiohttp.ClientError as e: LOGGER.error(f"Safety Alert API request failed: {e}") raise SafetyAlertConnectionError(f"Connection failed: {e}") except Exception as e: LOGGER.error(f"Unexpected error in Safety Alert API request: {e}") raise SafetyAlertDataError(f"Unexpected error: {e}")
def parse_alert_data(self, alerts: List[Dict[str, Any]]) -> Dict[str, Any]: """Parse and organize alert data.""" if not alerts: return { "total_alerts": 0, "latest_alert": None, "alert_types": {}, "alerts_by_type": {} }
# Count alerts by type alert_types = {} alerts_by_type = {}
for alert in alerts: alert_type = alert.get("DSSTR_SE_NM", "기타") if alert_type not in alert_types: alert_types[alert_type] = 0 alerts_by_type[alert_type] = []
alert_types[alert_type] += 1 alerts_by_type[alert_type].append({ "message": alert.get("MSG_CN", ""), "created_date": alert.get("CREAT_DT", ""), "area": alert.get("RCV_AREA_NM", ""), "emergency_level": alert.get("EMRGNCY_STEP_NM", "") })
# Get latest alert latest_alert = None if alerts: latest_alert = { "type": alerts[0].get("DSSTR_SE_NM", ""), "message": alerts[0].get("MSG_CN", ""), "created_date": alerts[0].get("CREAT_DT", ""), "area": alerts[0].get("RCV_AREA_NM", ""), "emergency_level": alerts[0].get("EMRGNCY_STEP_NM", "") }
return { "total_alerts": len(alerts), "latest_alert": latest_alert, "alert_types": alert_types, "alerts_by_type": alerts_by_type }
